// Generated by `pnpm bones:capture`: one `<name>.bones.json` per named skeleton, captured from the
// Storybook stories titled `Bones/…`. Never edit the JSON by hand. Typed loosely so the published
// declarations don't reference boneyard-js, which consumers don't install; the JSON is boneyard's
// own output and `registerBones` takes it as-is.
const modules = import.meta.glob('./*.bones.json', { eager: true, import: 'default' });

export const bones: Record<string, unknown> = Object.fromEntries(
  Object.entries(modules).map(([path, data]) => [path.replace(/^\.\//, '').replace(/\.bones\.json$/, ''), data]),
);
